            var baseBarCovers = 1000;
            var barCovers = Math.round(baseBarCovers * seasonFactor * repFactor * promoBoost * noise);
            if (d.promoFocus === 'upselling') barCovers = Math.round(barCovers * 1.10);
            barCovers = Math.max(300, Math.min(2000, barCovers));

            var baseRSOrders = 667;
            var rsOrders = Math.round(baseRSOrders * occupancy * 1.5 * noise);
            rsOrders = Math.max(200, Math.min(1200, rsOrders));

            var mainRevenue = mainCovers * d.menuPrice;
            var barADR = 14;
            if (d.promoFocus === 'upselling') barADR = 16;
            var barRevenue = barCovers * barADR;
            var rsRevenue = rsOrders * 28;

            var eventRevenue = 0;
            var eventCovers = 0;
            var eventAccepted = false;
            if (d.eventAccept) {
                var acceptProb = 1.0;
                if (d.eventPrice > round.eventBudget * 1.15) {
                    acceptProb = Math.max(0.1, 1 - (d.eventPrice - round.eventBudget * 1.15) / (round.eventBudget * 0.5));
                }
                if (Math.random() < acceptProb) {
                    eventAccepted = true;
                    eventCovers = round.eventGuests;
                    eventRevenue = eventCovers * d.eventPrice;
                }
            }

            var totalRevenue = mainRevenue + barRevenue + rsRevenue + eventRevenue;
            var totalCovers = mainCovers + barCovers + rsOrders + eventCovers;

            var mainCOGSPct = 0.28 + freshPct * 0.07 + strategyCostAdj;
            var mainCOGS = mainRevenue * mainCOGSPct;
            var barCOGS = barRevenue * 0.20;
            var rsCOGS = rsRevenue * 0.38;
            var eventCOGS = eventRevenue * 0.28;
            var totalCOGS = mainCOGS + barCOGS + rsCOGS + eventCOGS;

            var wastePct = freshPct * 0.05 * (1.2 - occupancy);
            var wasteCost = (mainCOGS + eventCOGS) * wastePct;
            totalCOGS += wasteCost;

            var foodCostPct = totalRevenue > 0 ? (totalCOGS / totalRevenue) * 100 : 0;

            var chefCost = 6500;
            var cookCost = d.cookTier * 2000;
            var serverCost = d.serverCount * 1500;
            var casualCost = d.casualHours * 30 * 25;
            var totalLabor = chefCost + cookCost + serverCost + casualCost;

            var operatingSupplies = totalRevenue * 0.05;
            var ccProcessing = totalRevenue * 0.03;

            var ebitda = totalRevenue - totalCOGS - totalLabor - operatingSupplies - ccProcessing - d.promoSpend;

            var cookCapacity = [0, 100, 150, 200][d.cookTier] || 150;
            var dailyMainCovers = mainCovers / 30;
            var kitchenUtil = dailyMainCovers / cookCapacity;

            var coversPerServer = (mainCovers + barCovers) / 30 / d.serverCount;
            var serverQuality = coversPerServer < 4 ? 1.0 : coversPerServer < 6 ? 0.9 : coversPerServer < 8 ? 0.75 : 0.5;

            var kitchenQuality = kitchenUtil < 0.85 ? 1.0 : kitchenUtil < 1.0 ? 0.85 : kitchenUtil < 1.2 ? 0.65 : 0.4;

            var freshQuality = 0.6 + freshPct * 0.4;

            var qualityInvestBonus = 0;
            if (d.promoFocus === 'quality') qualityInvestBonus = (d.promoSpend / 15000) * 0.5;

            var rawSatisfaction = 3.5 + serverQuality * 2.0 + kitchenQuality * 2.0 + freshQuality * 2.0 + qualityInvestBonus;
            var valuePenalty = 0;
            if (d.menuPrice > 60) valuePenalty = (d.menuPrice - 60) * 0.03;
            rawSatisfaction -= valuePenalty;
            rawSatisfaction = Math.max(1, Math.min(10, rawSatisfaction));

            ds.guestSatisfaction = Math.round((ds.guestSatisfaction * 0.3 + rawSatisfaction * 0.7) * 10) / 10;
            ds.reputation = Math.round((ds.reputation * 0.5 + ds.guestSatisfaction * 0.5) * 10) / 10;

            var totalLaborHours = (1 * 180) + (d.cookTier * 180) + (d.serverCount * 160) + (d.casualHours * 30);
            var laborProductivity = totalLaborHours > 0 ? Math.round((totalCovers / totalLaborHours) * 10) / 10 : 0;

            ds.cash += ebitda;
            ds.totalRevenue += totalRevenue;
            ds.totalCOGS += totalCOGS;
            ds.totalLabor += totalLabor;
            ds.totalPromoSpend += d.promoSpend;
            ds.totalEventRevenue += eventRevenue;
            ds.totalEBITDA += ebitda;
            ds.cumulativeCovers += totalCovers;
            ds.cumulativeLaborHours += totalLaborHours;

            ds.profitHistory.push(Math.round(ebitda));
            ds.revenueHistory.push(Math.round(totalRevenue));
            ds.satisfactionHistory.push(ds.guestSatisfaction);
            ds.foodCostPctHistory.push(Math.round(foodCostPct * 10) / 10);
            ds.eventRevenueHistory.push(Math.round(eventRevenue));
            ds.laborProdHistory.push(laborProductivity);

            var eventRevPct = ds.totalRevenue > 0 ? (ds.totalEventRevenue / ds.totalRevenue) * 100 : 0;

            var avgSatisfactionSoFar = ds.satisfactionHistory.reduce(function(s, v) { return s + v; }, 0) / ds.satisfactionHistory.length;
            var avgFoodCostSoFar = ds.foodCostPctHistory.reduce(function(s, v) { return s + v; }, 0) / ds.foodCostPctHistory.length;
            var laborProdAvgSoFar = ds.laborProdHistory.reduce(function(s, v) { return s + v; }, 0) / ds.laborProdHistory.length;
            var eventRevPctSoFar = ds.totalRevenue > 0 ? (ds.totalEventRevenue / ds.totalRevenue) * 100 : 0;
            var ebitdaScoreSoFar = Math.min(30, (ds.totalEBITDA / 800000) * 30);
            var foodCostScoreSoFar = 5;
            if (avgFoodCostSoFar >= 28 && avgFoodCostSoFar <= 35) { foodCostScoreSoFar = 15; }
            else if (avgFoodCostSoFar >= 25 && avgFoodCostSoFar <= 38) { foodCostScoreSoFar = 10; }
            var satisfactionScoreSoFar = Math.min(20, (avgSatisfactionSoFar / 10) * 20);
            var eventScoreSoFar = Math.min(20, (eventRevPctSoFar / 25) * 20);
            var laborScoreSoFar = Math.min(15, (laborProdAvgSoFar / 6) * 15);
            var cfiSoFar = Math.round(ebitdaScoreSoFar + foodCostScoreSoFar + satisfactionScoreSoFar + eventScoreSoFar + laborScoreSoFar);
            var overallScore = Math.max(0, Math.min(100, cfiSoFar));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });
            /* overallScore mirrors getPerformanceSummary cfi, computed from the running domainState totals so far, already on a 0 to 100 scale */

            var monthLabel = window.mySimulation.t('month_' + round.key);
            var resultsHtml = '<strong>' + window.mySimulation.t('results_month_heading').split('{month}').join(monthLabel) + '</strong><br>';
            resultsHtml += window.mySimulation.t('results_main').split('{covers}').join(mainCovers).split('{price}').join(d.menuPrice).split('{revenue}').join('$' + Math.round(mainRevenue).toLocaleString()) + '<br>';
            resultsHtml += window.mySimulation.t('results_bar').split('{covers}').join(barCovers).split('{revenue}').join('$' + Math.round(barRevenue).toLocaleString()) + '<br>';
            resultsHtml += window.mySimulation.t('results_roomservice').split('{orders}').join(rsOrders).split('{revenue}').join('$' + Math.round(rsRevenue).toLocaleString()) + '<br>';
            if (d.eventAccept) {
                var eventTypeLabel = window.mySimulation.t(round.key + '_event_type');
                if (eventAccepted) {
                    resultsHtml += window.mySimulation.t('results_event_accepted').split('{type}').join(eventTypeLabel).split('{guests}').join(eventCovers).split('{price}').join(d.eventPrice).split('{revenue}').join('$' + Math.round(eventRevenue).toLocaleString()) + '<br>';
                } else {
                    resultsHtml += window.mySimulation.t('results_event_declined_client').split('{type}').join(eventTypeLabel) + '<br>';
                }
            } else {
                resultsHtml += window.mySimulation.t('results_event_declined_you') + '<br>';
            }
            resultsHtml += '<br>' + window.mySimulation.t('results_total_revenue').split('{revenue}').join('$' + Math.round(totalRevenue).toLocaleString());
            resultsHtml += ' | ' + window.mySimulation.t('results_cogs').split('{cogs}').join('$' + Math.round(totalCOGS).toLocaleString()).split('{pct}').join(foodCostPct.toFixed(1));
            resultsHtml += ' | ' + window.mySimulation.t('results_labor').split('{labor}').join('$' + Math.round(totalLabor).toLocaleString());
            resultsHtml += '<br><strong>' + window.mySimulation.t('results_ebitda').split('{ebitda}').join('$' + Math.round(ebitda).toLocaleString()) + '</strong>';
            resultsHtml += ' | ' + window.mySimulation.t('results_satisfaction').split('{value}').join(ds.guestSatisfaction.toFixed(1));

            var resultsPanel = document.getElementById('resultsPanel');
            var resultsContent = document.getElementById('resultsContent');
            if (resultsPanel && resultsContent) {
                resultsContent.innerHTML = resultsHtml;
                resultsPanel.style.display = 'block';
            }

            var period = state.currentPeriod;
            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                month: monthLabel,
                mainCovers: mainCovers,
                barCovers: barCovers,
                rsOrders: rsOrders,
                eventAccepted: eventAccepted,
                eventCovers: eventCovers,
                totalRevenue: Math.round(totalRevenue),
                totalCOGS: Math.round(totalCOGS),
                totalLabor: Math.round(totalLabor),
                foodCostPct: Math.round(foodCostPct * 10) / 10,
                ebitda: Math.round(ebitda),
                satisfaction: ds.guestSatisfaction,
                laborProductivity: laborProductivity,
                eventRevenue: Math.round(eventRevenue),
                eventRevPct: Math.round(eventRevPct * 10) / 10,
                cash: Math.round(ds.cash)
            };
        }

