        getPerformanceSummary(history) {
            if (!history.length) return {};

            var totalEBITDA = 0;
            var totalRevenue = 0;
            var totalEventRev = 0;
            var totalCovers = 0;
            var totalLaborHrs = 0;
            var satisfactionSum = 0;
            var foodCostSum = 0;

            for (var i = 0; i < history.length; i++) {
                var r = history[i].results || {};
                totalEBITDA += r.ebitda || 0;
                totalRevenue += r.totalRevenue || 0;
                totalEventRev += r.eventRevenue || 0;
                satisfactionSum += r.satisfaction || 0;
                foodCostSum += r.foodCostPct || 0;
                totalCovers += (r.mainCovers || 0) + (r.barCovers || 0) + (r.rsOrders || 0) + (r.eventCovers || 0);
            }

            var avgSatisfaction = satisfactionSum / history.length;
            var avgFoodCost = foodCostSum / history.length;
            var eventRevPct = totalRevenue > 0 ? (totalEventRev / totalRevenue) * 100 : 0;

            var ebitdaScore = Math.min(30, (totalEBITDA / 800000) * 30);
            var foodCostScore = 0;
            if (avgFoodCost >= 28 && avgFoodCost <= 35) {
                foodCostScore = 15;
            } else if (avgFoodCost >= 25 && avgFoodCost <= 38) {
                foodCostScore = 10;
            } else {
                foodCostScore = 5;
            }
            var satisfactionScore = Math.min(20, (avgSatisfaction / 10) * 20);
            var eventScore = Math.min(20, (eventRevPct / 25) * 20);
            var laborProdAvg = 0;
            for (var j = 0; j < history.length; j++) {
                laborProdAvg += (history[j].results || {}).laborProductivity || 0;
            }
            laborProdAvg = laborProdAvg / history.length;
            var laborScore = Math.min(15, (laborProdAvg / 6) * 15);

            var cfi = Math.round(ebitdaScore + foodCostScore + satisfactionScore + eventScore + laborScore);

            var performance = window.mySimulation.t('perf_needs_improvement');
            if (cfi >= 80) performance = window.mySimulation.t('perf_outstanding');
            else if (cfi >= 65) performance = window.mySimulation.t('perf_excellent');
            else if (cfi >= 50) performance = window.mySimulation.t('perf_good');
            else if (cfi >= 35) performance = window.mySimulation.t('perf_developing');

            var insights = [];
            if (totalEBITDA > 600000) insights.push(window.mySimulation.t('insight_profit_strong'));
            if (totalEBITDA < 300000) insights.push(window.mySimulation.t('insight_profit_weak'));
            if (avgSatisfaction >= 8) insights.push(window.mySimulation.t('insight_satisfaction_strong'));
            if (avgSatisfaction < 6) insights.push(window.mySimulation.t('insight_satisfaction_weak'));
            if (avgFoodCost > 35) insights.push(window.mySimulation.t('insight_foodcost_high'));
            if (avgFoodCost < 28) insights.push(window.mySimulation.t('insight_foodcost_low'));
            if (eventRevPct > 15) insights.push(window.mySimulation.t('insight_event_strong'));
            if (eventRevPct < 5) insights.push(window.mySimulation.t('insight_event_weak'));

            return {
                totalEBITDA: totalEBITDA,
                totalRevenue: totalRevenue,
                avgSatisfaction: Math.round(avgSatisfaction * 10) / 10,
                avgFoodCostPct: Math.round(avgFoodCost * 10) / 10,
                eventRevenuePct: Math.round(eventRevPct * 10) / 10,
                laborProductivity: Math.round(laborProdAvg * 10) / 10,
                cfi: cfi,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
