            if (results.ebitda < 0) return window.mySimulation.t('hint_loss');
            if (results.foodCostPct > 36) return window.mySimulation.t('hint_high_cost');
            if (results.satisfaction < 5.5) return window.mySimulation.t('hint_low_satisfaction');
            if (results.laborProductivity < 2.5) return window.mySimulation.t('hint_overstaffed');
            if (results.laborProductivity > 7) return window.mySimulation.t('hint_understaffed');
            if (!results.eventAccepted && state.decisions.eventAccept) return window.mySimulation.t('hint_event_rejected');
            if (results.ebitda > 100000) return window.mySimulation.t('hint_great_month');
            return null;
        }

